            if (d1) decisions.decision1 = parseInt(d1.value);
            if (d2) decisions.decision2 = parseInt(d2.value);
            if (d3) decisions.decision3 = parseInt(d3.value);

            if (!decisions.decision1 || !decisions.decision2 || !decisions.decision3) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var picks = [d.decision1, d.decision2, d.decision3];
            var past = (ds.choiceHistory || []).slice(0, roundIdx);
            var carry = this._carry(past, ds.safetyScore, roundIdx);
            var allDecs = [round.d1, round.d2, round.d3];

            var learningGain = 0;
            var safetyGain = 0;
            var riskGain = 0;
            var revenueGain = 0;
            var maxPossible = 0;

            for (var i = 0; i < allDecs.length; i++) {
                var opts = allDecs[i].options;
                var bestTotal = 0;
                for (var j = 0; j < opts.length; j++) {
                    var optTotal = opts[j].learning + Math.max(0, opts[j].safety) + opts[j].risk;
                    if (optTotal > bestTotal) bestTotal = optTotal;
                    if (opts[j].value === picks[i]) {
                        var share = this._share(carry, roundIdx, i, opts[j].value);
                        learningGain += opts[j].learning * share;
                        safetyGain += opts[j].safety > 0 ? opts[j].safety * share : opts[j].safety;
                        riskGain += opts[j].risk * share;
                        revenueGain += opts[j].revenue * share;
                    }
                }
                maxPossible += bestTotal;
            }

            var learningDelta = Math.round(learningGain * 3);
            var safetyDelta = Math.round(safetyGain * 5);
            var riskDelta = Math.round(riskGain * 5);
            revenueGain = Math.round(revenueGain / 1000) * 1000;

            ds.learningScore = Math.max(0, Math.min(100, ds.learningScore + learningDelta));
            ds.safetyScore = Math.max(0, Math.min(100, ds.safetyScore + safetyDelta));
            ds.riskScore = Math.max(0, Math.min(100, ds.riskScore + riskDelta));
            ds.revenueProtected = Math.min(ds.totalRevAtRisk, ds.revenueProtected + revenueGain);

            var actualTotal = learningGain + Math.max(0, safetyGain) + riskGain;
            var roundScore = maxPossible > 0 ? Math.round((actualTotal / maxPossible) * 100) : 0;

            past.push(picks);
            ds.choiceHistory = past;
            ds.learningHistory.push(ds.learningScore);
            ds.safetyHistory.push(ds.safetyScore);
            ds.riskHistory.push(ds.riskScore);
            ds.revenueHistory.push(ds.revenueProtected);
            ds.roundScoreHistory.push(roundScore);

            // Platform score: running average of roundScore so far, same metric getPerformanceSummary averages into avgScore
            var scoreSum = 0;
            for (var si = 0; si < ds.roundScoreHistory.length; si++) {
                scoreSum += ds.roundScoreHistory[si];
            }
            var overallScore = Math.round(scoreSum / ds.roundScoreHistory.length);
            overallScore = Math.max(0, Math.min(100, overallScore));
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: overallScore });

            this._renderFeedback(round, roundIdx, roundScore, carry, picks);

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: state.currentPeriod,
                roundScore: roundScore,
                learningGain: learningDelta,
                safetyGain: safetyDelta,
                riskGain: riskDelta,
                revenueGain: revenueGain,
                learningScore: ds.learningScore,
                safetyScore: ds.safetyScore,
                riskScore: ds.riskScore,
                revenueProtected: ds.revenueProtected,
                choices: picks,
                carryReview: carry.review,
                carryPremortem: carry.premortem,
                carryTrust: carry.trust,
                safetyAtStart: carry.safety
            };
        }

        // What earlier rounds carry into this one. Round 2: the review reaches less when its chair is not
        // independent or it opened with conclusions. Round 3: the pre-mortem and the supervision of the
        // managing partner deliver in proportion to the psychological safety built so far.
        _carry(past, safetyNow, roundIdx) {
            var c = this.CARRY;
            var out = { review: 1, premortem: 1, trust: 1, chair: false, opening: false, safety: safetyNow };
            if (roundIdx === 1 && past[0]) {
                if (past[0][0] !== 2) { out.review *= c.chair; out.chair = true; }
                if (past[0][1] === 3) { out.review *= c.opening; out.opening = true; }
            }
            if (roundIdx === 2) {
                out.trust = Math.max(0, Math.min(1, (safetyNow - c.safetyStart) / (c.safetyFull - c.safetyStart)));
                out.premortem = Math.max(c.premortemFloor, out.trust);
            }
            return out;
        }

        _share(carry, roundIdx, decisionIdx, value) {
            if (roundIdx === 1) return carry.review;
            if (roundIdx === 2) {
                if (decisionIdx === 2) return value === 2 ? carry.trust : 1;
                return carry.premortem;
            }
            return 1;
        }

        _renderFeedback(round, roundIdx, roundScore, carry, picks) {
            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (!feedbackPanel || !feedbackText) return;
            var t = window.mySimulation.t.bind(window.mySimulation);
            var fbLevel = '_low';
            if (roundScore >= 80) fbLevel = '_high';
            else if (roundScore >= 50) fbLevel = '_mid';
            var parts = [t(round.feedbackKey + fbLevel)];
            if (roundIdx === 1 && carry.chair) parts.push(t('fb_carry_chair'));
            if (roundIdx === 1 && carry.opening) parts.push(t('fb_carry_opening'));
            if (roundIdx === 2 && carry.premortem < 1) parts.push(t('fb_carry_premortem'));
            if (roundIdx === 2 && carry.trust < 1 && picks[2] === 2) parts.push(t('fb_carry_trust'));
            var html = '';
            for (var i = 0; i < parts.length; i++) html += '<p>' + parts[i] + '</p>';
            feedbackPanel.style.display = 'block';
            feedbackText.innerHTML = html;
        }

