        getPerformanceSummary(history) {
            if (!history.length) return {};
            var self = this;
            var t = function(k) { return self._tx(k, k); };
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = Math.max(0, Math.min(100, Math.round(totalScore / scores.length)));
            var lastEntry = history[history.length - 1];
            var last = lastEntry.results || {};
            var tier = this.TIERS[this.TIERS.length - 1].id;
            for (var ti = 0; ti < this.TIERS.length; ti++) {
                if (avgScore >= this.TIERS[ti].min) { tier = this.TIERS[ti].id; break; }
            }

            // Turning point: the lowest round, the earliest one on a tie.
            var low = 0;
            for (var i = 1; i < scores.length; i++) { if (scores[i] < scores[low]) low = i; }
            var turning = scores[low] >= 100 ? t('db_turn_none')
                : t('db_turn').replace('{n}', String(low + 1)).replace('{s}', String(scores[low]));

            // What this run did, read from its own choices. Nothing is said about a choice that was not made.
            var ch = history.map(function(r) { return (r.results && r.results.choices) || null; });
            var keys = [];
            if (ch[0]) {
                if (ch[0][0] === 1) keys.push('db_m_chair_mp');
                if (ch[0][0] === 3) keys.push('db_m_chair_vidal');
                if (ch[0][1] === 3) keys.push('db_m_opening');
            }
            if (ch[1]) {
                if (ch[1][0] === 1) keys.push('db_m_level2');
                if (ch[1][1] === 1) keys.push('db_m_individual');
                if (ch[1][2] === 2) keys.push('db_m_private');
                if (ch[1][2] === 3) keys.push('db_m_avoid');
            }
            if (ch[2]) {
                if (ch[2][2] === 1) keys.push('db_m_vidal');
            }
            if (ch[3]) {
                if (ch[3][0] === 1) keys.push('db_m_general');
                if (ch[3][1] === 2) keys.push('db_m_comp');
                if (ch[3][1] === 3) keys.push('db_m_noaction');
                if (ch[3][2] === 2) keys.push('db_m_optional');
                if (ch[3][2] === 3) keys.push('db_m_nophase');
            }
            var insights = keys.map(function(k) { return t(k); });
            var r2 = history[1] && history[1].results;
            var r3 = history[2] && history[2].results;
            if (r2 && r2.carryReview < 1) insights.push(t('db_c_review').replace('{p}', String(Math.round(r2.carryReview * 100))));
            if (r3 && r3.carryPremortem < 1) {
                insights.push(t('db_c_premortem').replace('{s}', String(Math.round(r3.safetyAtStart))).replace('{p}', String(Math.round(r3.carryPremortem * 100))));
            }
            if (!insights.length) insights.push(t('db_none'));

            return {
                avgScore: avgScore,
                overallScore: avgScore,
                totalScore: avgScore,
                score: avgScore,
                composite: avgScore,
                roundScores: scores,
                finalLearning: last.learningScore || 0,
                finalSafety: last.safetyScore || 0,
                finalRisk: last.riskScore || 0,
                revenueProtected: last.revenueProtected || 0,
                performance: tier,
                performanceKey: tier,
                performanceLabel: t('tier_' + tier),
                turningPoint: turning,
                mistakeKeys: keys,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var t = function(k) { return self._tx(k, k); };
            var es = this._lang() === 'es';
            var money = String(Math.round(summary.revenueProtected || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, es ? '.' : ',');
            var rounds = (summary.roundScores || []).map(function(s) { return s + (es ? ' %' : '%'); }).join(' · ');
            var list = summary.insights || [];
            var items = '';
            for (var i = 0; i < list.length; i++) items += '<li>' + list[i] + '</li>';
            var outcome = t('db_outcome').replace('{l}', String(summary.finalLearning || 0)).replace('{s}', String(summary.finalSafety || 0))
                .replace('{k}', String(summary.finalRisk || 0)).replace('{r}', money);
            return '<div class="completion-message usf-debrief despues-sim-debrief p-4">' +
                '<div class="usf-debrief-tier">' + (summary.performanceLabel || '') + '</div>' +
                '<p>' + t('db_score').replace('{s}', String(summary.avgScore || 0)) + '</p>' +
                '<h4 class="usf-debrief-h">' + t('db_turn_h') + '</h4><p>' + (summary.turningPoint || '') + '</p>' +
                '<h4 class="usf-debrief-h">' + t('db_run_h') + '</h4><ul class="usf-debrief-list">' + items + '</ul>' +
                '<h4 class="usf-debrief-h">' + t('db_res_h') + '</h4><p>' + t('db_process').replace('{a}', rounds) + '</p><p>' + outcome + '</p>' +
                '<h4 class="usf-debrief-h">' + t('db_q_h') + '</h4><ol class="usf-debrief-list"><li>' + t('db_q1') + '</li><li>' + t('db_q2') + '</li><li>' + t('db_q3') + '</li></ol>' +
                '</div>';
        }

        _lang() {
